/* ===========================================================
   Nxeon Mail - mailcow UI brand theme (dark-navy + violet)
   Loaded last from data/web/css/build so it overrides mailcow.
   Color-only overrides - no layout/behavior changes.
   =========================================================== */
:root{
  --nx-navy:#060a14;
  --nx-navy-2:#0a101f;
  --nx-navy-3:#111829;
  --nx-violet:#6f47f5;
  --nx-violet-d:#5a37d6;
  --nx-violet-l:#8a63ff;
  --nx-blue:#3b82f6;
  --nx-ink:#e6e9f2;
}

/* Page background */
body{ background:var(--nx-navy-2) !important; }

/* Top navbar -> dark navy with violet accent underline */
.navbar.bg-light,
nav.navbar.navbar-light.bg-light{
  background:linear-gradient(90deg,var(--nx-navy) 0%,var(--nx-navy-2) 100%) !important;
  border-bottom:2px solid var(--nx-violet) !important;
}
.navbar.bg-light .navbar-brand,
.navbar.bg-light .nav-link,
.navbar.bg-light .dropdown-toggle,
.navbar-light .navbar-nav .nav-link,
.navbar.bg-light .form-check-label,
.navbar.bg-light .navbar-text{
  color:var(--nx-ink) !important;
}
.navbar.bg-light .nav-link:hover,
.navbar-light .navbar-nav .nav-link:hover,
.navbar-light .navbar-nav .nav-link:focus{ color:#ffffff !important; }
.navbar-toggler{ border-color:rgba(255,255,255,.35) !important; }
.navbar-toggler-icon{ filter:invert(1) brightness(1.6); }
.navbar-brand img.main-logo,
.navbar-brand img.main-logo-dark{ height:34px; width:auto; }

/* Primary accents -> violet */
.btn-primary{
  background-color:var(--nx-violet) !important;
  border-color:var(--nx-violet) !important;
}
.btn-primary:hover,.btn-primary:focus,.btn-primary:active,
.btn-primary.active,.btn-primary:not(:disabled):not(.disabled):active{
  background-color:var(--nx-violet-d) !important;
  border-color:var(--nx-violet-d) !important;
}
.btn-outline-primary{ color:var(--nx-violet) !important; border-color:var(--nx-violet) !important; }
.btn-outline-primary:hover{ background-color:var(--nx-violet) !important; color:#fff !important; }
.badge.bg-primary,.bg-primary{ background-color:var(--nx-violet) !important; }
.text-primary{ color:var(--nx-violet) !important; }
.progress-bar{ background-color:var(--nx-violet) !important; }
.page-item.active .page-link{ background-color:var(--nx-violet) !important; border-color:var(--nx-violet) !important; }
.form-check-input:checked{ background-color:var(--nx-violet) !important; border-color:var(--nx-violet) !important; }
.nav-tabs .nav-link.active{ color:var(--nx-violet) !important; }
.nav-pills .nav-link.active,.nav-pills .show>.nav-link{ background-color:var(--nx-violet) !important; }

/* Links */
a{ color:var(--nx-blue); }
a:hover{ color:var(--nx-violet); }
.navbar a:hover{ color:#ffffff; }

/* Login page: navy backdrop behind the login card */
body.bg-white,.login-container{ background:radial-gradient(1200px 600px at 50% -10%,var(--nx-navy-3) 0%,var(--nx-navy-2) 45%,var(--nx-navy) 100%) !important; }

